// src/pages/Representative.jsx
import React, { useState } from 'react';
import { useAuth } from '../hooks/useAuth.js';
import { useClaim } from '../hooks/useClaim.js';
import { useAutoDismiss } from '../hooks/useTimer.js';
import SearchBar from '../components/common/SearchBar.jsx';
import ClaimCard from '../components/common/ClaimCard.jsx';
import EmptyState from '../components/common/EmptyState.jsx';
import PopupOptions from '../components/common/PopupOptions.jsx';
import ToggleGroup from '../components/common/ToggleGroup.jsx';
import TransactionForm from '../components/common/TransactionForm.jsx';
import RoleNav from '../components/navigation/RoleNav.jsx';
import { STEP_TYPES } from '../constants/roles.js';
import './Representative.css';

const Representative = () => {
  const { user } = useAuth();
  const { currentClaim, fetchClaim, setCurrentClaim, isLoading } = useClaim();
  const [searchValue, setSearchValue] = useState('255781518973');
  const [step, setStep] = useState(STEP_TYPES.SEARCH);
  const [selectedOption, setSelectedOption] = useState(null);
  const [selectedType, setSelectedType] = useState(null);

  const [txData, setTxData] = useState({
    amount: '',
    txId: '',
    screenshot: null,
    date: '06/22/2026',
    rep: user?.name || 'Shabani'
  });

  // Use auto-dismiss hook for popup
  const { 
    isVisible: isPopupVisible, 
    show: showPopup, 
    dismiss: dismissPopup,
    progress: popupProgress 
  } = useAutoDismiss(4000, () => {
    // When popup auto-dismisses, go back to details
    if (step === STEP_TYPES.POPUP) {
      setStep(STEP_TYPES.DETAILS);
    }
  });

  const handleSearch = async () => {
    if (!searchValue.trim()) return;
    try {
      const data = await fetchClaim(searchValue.trim());
      if (data) {
        setStep(STEP_TYPES.DETAILS);
      }
    } catch (error) {
      alert('Error fetching claim: ' + error.message);
    }
  };

  const handleAddPayment = () => {
    setStep(STEP_TYPES.POPUP);
    showPopup();
  };

  const handleOptionSelect = (option) => {
    dismissPopup();
    setSelectedOption(option);
    setStep(STEP_TYPES.TOGGLE);
  };

  const handleTypeSelect = (type) => {
    setSelectedType(type);
    if (selectedOption === 'Replacement') {
      setStep(STEP_TYPES.TRANSACTION);
    } else if (selectedOption === 'Repair' && type === 'Excess') {
      setStep(STEP_TYPES.PENDING);
    } else {
      setStep(STEP_TYPES.TRANSACTION);
    }
  };

  const handleTxChange = (e) => {
    const { name, value } = e.target;
    setTxData(prev => ({ ...prev, [name]: value }));
    // Auto-fill date when txId is entered
    if (name === 'txId' && value.length > 2) {
      setTxData(prev => ({ ...prev, date: '06/22/2026' }));
    }
  };

  const handleSubmitTx = () => {
    // Check if screenshot is uploaded
    if (!txData.screenshot) {
      alert('Please upload a transaction screenshot');
      return;
    }

    // Log the transaction data with screenshot
    console.log('Transaction Data:', {
      ...txData,
      screenshot: {
        name: txData.screenshot.name,
        size: txData.screenshot.size,
        type: txData.screenshot.type,
        base64: txData.screenshot.base64.substring(0, 100) + '...' // Truncated for logging
      }
    });

    alert('✅ Transaction submitted successfully with screenshot!');
    resetFlow();
  };

  const handleCancel = () => {
    resetFlow();
  };

  const resetFlow = () => {
    setStep(STEP_TYPES.SEARCH);
    setCurrentClaim(null);
    setSelectedOption(null);
    setSelectedType(null);
    setTxData({
      amount: '',
      txId: '',
      screenshot: null,
      date: '06/22/2026',
      rep: user?.name || 'Shabani'
    });
    dismissPopup();
  };

  const renderContent = () => {
    switch (step) {
      case STEP_TYPES.SEARCH:
        return (
          <>
            <SearchBar
              value={searchValue}
              onChange={setSearchValue}
              onSearch={handleSearch}
              isLoading={isLoading}
            />
            <EmptyState 
              icon="fa-search"
              title="No claim loaded"
              description="Search for a claim using phone number"
            />
          </>
        );
      
      case STEP_TYPES.DETAILS:
        return (
          <>
            <SearchBar
              value={searchValue}
              onChange={setSearchValue}
              onSearch={handleSearch}
              isLoading={isLoading}
            />
            <ClaimCard 
              claim={currentClaim}
              representative={user?.name || 'Shabani'}
              onAddPayment={handleAddPayment}
            />
          </>
        );
      
      case STEP_TYPES.POPUP:
        return (
          <>
            <SearchBar
              value={searchValue}
              onChange={setSearchValue}
              onSearch={handleSearch}
              isLoading={isLoading}
            />
            <PopupOptions 
              onSelect={handleOptionSelect}
              onTimeout={dismissPopup}
              timeoutDuration={4000}
            />
            {isPopupVisible && (
              <div className="popup-progress-bar">
                <div 
                  className="popup-progress-fill" 
                  style={{ width: `${popupProgress}%` }}
                />
              </div>
            )}
          </>
        );
      
      case STEP_TYPES.TOGGLE:
        return (
          <>
            <SearchBar
              value={searchValue}
              onChange={setSearchValue}
              onSearch={handleSearch}
              isLoading={isLoading}
            />
            <ToggleGroup 
              selected={selectedType}
              onSelect={handleTypeSelect}
              title={selectedOption}
            />
          </>
        );
      
      case STEP_TYPES.TRANSACTION:
        return (
          <>
            <SearchBar
              value={searchValue}
              onChange={setSearchValue}
              onSearch={handleSearch}
              isLoading={isLoading}
            />
            <TransactionForm 
              title={`${selectedOption} · ${selectedType}`}
              isReplacement={selectedOption === 'Replacement'}
              txData={txData}
              onChange={handleTxChange}
              onSubmit={handleSubmitTx}
              onCancel={handleCancel}
              representative={user?.name || 'Shabani'}
            />
          </>
        );
      
      case STEP_TYPES.PENDING:
        return (
          <>
            <SearchBar
              value={searchValue}
              onChange={setSearchValue}
              onSearch={handleSearch}
              isLoading={isLoading}
            />
            <TransactionForm 
              title="Repair · Excess"
              isReplacement={false}
              txData={txData}
              onChange={handleTxChange}
              onSubmit={handleSubmitTx}
              onCancel={handleCancel}
              isPending={true}
              representative={user?.name || 'Shabani'}
            />
          </>
        );
      
      default:
        return null;
    }
  };

  return (
    <div className="representative-page">
      <div className="rep-header">
        <i className="fas fa-headset"></i>
        <h2>Claim Management <span className="subtitle">Representative</span></h2>
      </div>
      
      <RoleNav activeRole="rep" onRoleChange={() => {}} />
      
      <div className="rep-content step-transition">
        {renderContent()}
      </div>
    </div>
  );
};

export default Representative;
